vector<int> twoSum(vector<int>& a, int t) {
    unordered_map<int,int> idx;  // value -> index
    for (int i = 0; i < (int)a.size(); i++) {
        auto it = idx.find(t - a[i]);
        if (it != idx.end()) return {it->second, i};
        idx[a[i]] = i;
    }
    return {};
}

int mostFrequent(vector<int>& a) {
    unordered_map<int,int> cnt;
    for (int x : a) cnt[x]++;      // count each value
    int best = 0, mode = a[0];
    for (auto& [v, c] : cnt)
        if (c > best) best = c, mode = v;
    return mode;
}
